// =========================================================================
// SELF-HOSTED LIBRARY AUDIT & AUTO-REPAIR ENGINE
// SS+2 High School Ghaghra • Educational Notes & Notices Portal
// Verifies notes/ and notices/ folder paths, fixes path associations,
// and automatically discovers & indexes unadded physical PDF files.
// =========================================================================

const LibraryRepairEngine = {
  // Normalize path strings for robust cross-comparison
  normalizePath(p) {
    if (!p || typeof p !== 'string') return '';
    let clean = p.trim().replace(/\\/g, '/');
    try {
      clean = decodeURIComponent(clean);
    } catch (e) {}
    if (!clean.startsWith('./') && !clean.startsWith('/') && !clean.startsWith('http')) {
      clean = './' + clean;
    }
    return clean.replace(/\/{2,}/g, '/').trim();
  },

  // Extract pure filename from path or URL
  getFilename(p) {
    if (!p || typeof p !== 'string') return '';
    const norm = p.replace(/\\/g, '/');
    const idx = norm.lastIndexOf('/');
    let fname = idx >= 0 ? norm.substring(idx + 1) : norm;
    try {
      fname = decodeURIComponent(fname);
    } catch (e) {}
    return fname.trim();
  },

  // Find exact or closest match in PHYSICAL_FILE_MANIFEST
  findMatchInManifest(urlOrPath) {
    if (!urlOrPath) return null;
    const targetNorm = this.normalizePath(urlOrPath).toLowerCase();
    const targetFile = this.getFilename(urlOrPath).toLowerCase();

    // 1. Exact relative path match
    for (const item of PHYSICAL_FILE_MANIFEST) {
      if (this.normalizePath(item.path).toLowerCase() === targetNorm) {
        return { match: item, exactPath: true };
      }
    }

    // 2. Exact filename match
    for (const item of PHYSICAL_FILE_MANIFEST) {
      if (item.filename.toLowerCase() === targetFile) {
        return { match: item, exactPath: false };
      }
    }

    // 3. Normalized stripped match (ignoring whitespace and special chars)
    const cleanTarget = targetFile.replace(/[^a-z0-9]/g, '');
    if (cleanTarget.length > 3) {
      for (const item of PHYSICAL_FILE_MANIFEST) {
        const cleanItem = item.filename.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (cleanItem === cleanTarget) {
          return { match: item, exactPath: false };
        }
      }
    }

    return null;
  },

  // Audit and Repair All Notes & Notices in Library
  async checkAndRepairLibrary(options = {}) {
    const showModal = Boolean(options.showModal === true);

    const report = {
      timestamp: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      totalManifest: PHYSICAL_FILE_MANIFEST.length,
      notesChecked: 0,
      noticesChecked: 0,
      healthyCount: 0,
      repairedNotes: [],
      repairedNotices: [],
      addedNotes: [],
      addedNotices: [],
      missingFiles: [],
      logs: []
    };

    report.logs.push({
      type: 'info',
      icon: '🚀',
      msg: `Starting library check across ${PHYSICAL_FILE_MANIFEST.length} self-hosted physical files...`
    });

    // 1. Load active data
    const customNotes = (typeof getCustomNotes === 'function') ? getCustomNotes() : [];
    const customPosters = (typeof getCustomPosters === 'function') ? (getCustomPosters() || []) : [];
    const repairedPaths = (typeof getRepairedPaths === 'function') ? getRepairedPaths() : {};
    let customNotesModified = false;
    let customPostersModified = false;
    let repairedPathsModified = false;

    // Track all indexed paths & filenames
    const indexedFilePaths = new Set();
    const indexedFilenames = new Set();

    // 2. Audit Classes Data (Default Notes)
    if (typeof CLASSES_DATA !== 'undefined') {
      for (const classKey in CLASSES_DATA) {
        const cls = CLASSES_DATA[classKey];
        if (!cls.subjects) continue;

        for (const subject of cls.subjects) {
          if (!subject.notes) continue;

          for (const note of subject.notes) {
            report.notesChecked++;
            const currentUrl = repairedPaths[note.id] || note.fileUrl;
            const filename = this.getFilename(currentUrl);

            indexedFilePaths.add(this.normalizePath(currentUrl).toLowerCase());
            indexedFilenames.add(filename.toLowerCase());

            const matchResult = this.findMatchInManifest(currentUrl);

            if (matchResult) {
              const manifestItem = matchResult.match;
              indexedFilePaths.add(this.normalizePath(manifestItem.path).toLowerCase());
              indexedFilenames.add(manifestItem.filename.toLowerCase());

              if (!matchResult.exactPath || this.normalizePath(currentUrl) !== this.normalizePath(manifestItem.path)) {
                // Path association error detected & fixed!
                repairedPaths[note.id] = manifestItem.path;
                repairedPathsModified = true;
                report.repairedNotes.push({
                  id: note.id,
                  title: note.title,
                  oldPath: currentUrl,
                  newPath: manifestItem.path,
                  reason: 'Folder path or slash typo association corrected'
                });
                report.logs.push({
                  type: 'repair',
                  icon: '🔧',
                  msg: `Repaired note path: "${note.title}" → ${manifestItem.path}`
                });
              } else {
                report.healthyCount++;
              }
            } else {
              // Path not in manifest
              report.missingFiles.push({
                id: note.id,
                title: note.title,
                url: currentUrl
              });
              report.logs.push({
                type: 'warn',
                icon: '⚠️',
                msg: `Unrecognized file path in catalog: "${note.title}" (${currentUrl})`
              });
            }
          }
        }
      }
    }

    // 3. Audit Custom Notes (User / Admin Uploads)
    for (let i = 0; i < customNotes.length; i++) {
      const note = customNotes[i];
      if (note.isBlob) {
        // Blob in IndexedDB - skip physical check
        report.notesChecked++;
        report.healthyCount++;
        continue;
      }

      report.notesChecked++;
      const currentUrl = note.fileUrl;
      const filename = this.getFilename(currentUrl);

      indexedFilePaths.add(this.normalizePath(currentUrl).toLowerCase());
      indexedFilenames.add(filename.toLowerCase());

      const matchResult = this.findMatchInManifest(currentUrl);
      if (matchResult) {
        const manifestItem = matchResult.match;
        indexedFilePaths.add(this.normalizePath(manifestItem.path).toLowerCase());
        indexedFilenames.add(manifestItem.filename.toLowerCase());

        if (!matchResult.exactPath || this.normalizePath(currentUrl) !== this.normalizePath(manifestItem.path)) {
          note.fileUrl = manifestItem.path;
          customNotesModified = true;
          report.repairedNotes.push({
            id: note.id,
            title: note.title,
            oldPath: currentUrl,
            newPath: manifestItem.path,
            reason: 'Custom note physical path repaired'
          });
          report.logs.push({
            type: 'repair',
            icon: '🔧',
            msg: `Repaired custom note: "${note.title}" → ${manifestItem.path}`
          });
        } else {
          report.healthyCount++;
        }
      }
    }

    // 4. Audit Notices (POSTERS_DATA & customPosters)
    const baseNotices = (typeof POSTERS_DATA !== 'undefined') ? POSTERS_DATA : [];
    const allNotices = (customPosters && customPosters.length > 0) ? customPosters : baseNotices;

    for (let i = 0; i < allNotices.length; i++) {
      const notice = allNotices[i];
      if (!notice.fileUrl || notice.isBlob) continue;

      report.noticesChecked++;
      const currentUrl = notice.fileUrl;
      const filename = this.getFilename(currentUrl);

      indexedFilePaths.add(this.normalizePath(currentUrl).toLowerCase());
      indexedFilenames.add(filename.toLowerCase());

      const matchResult = this.findMatchInManifest(currentUrl);
      if (matchResult) {
        const manifestItem = matchResult.match;
        indexedFilePaths.add(this.normalizePath(manifestItem.path).toLowerCase());
        indexedFilenames.add(manifestItem.filename.toLowerCase());

        if (!matchResult.exactPath || this.normalizePath(currentUrl) !== this.normalizePath(manifestItem.path)) {
          notice.fileUrl = manifestItem.path;
          customPostersModified = true;
          report.repairedNotices.push({
            id: notice.id,
            title: notice.title,
            oldPath: currentUrl,
            newPath: manifestItem.path
          });
          report.logs.push({
            type: 'repair',
            icon: '🔧',
            msg: `Repaired circular path: "${notice.title}" → ${manifestItem.path}`
          });
        } else {
          report.healthyCount++;
        }
      }
    }

    // 5. Scan PHYSICAL_FILE_MANIFEST for Unindexed Files and Auto-Add them!
    for (const item of PHYSICAL_FILE_MANIFEST) {
      const itemNorm = this.normalizePath(item.path).toLowerCase();
      const itemFile = item.filename.toLowerCase();

      const alreadyIndexed = indexedFilePaths.has(itemNorm) || indexedFilenames.has(itemFile);

      if (!alreadyIndexed) {
        if (item.type === 'notice') {
          // Add unindexed notice
          const title = item.filename.replace(/^Notice_/i, '').replace(/\.pdf$/i, '').replace(/_/g, ' ');
          const newNotice = {
            id: Date.now() + Math.floor(Math.random() * 1000),
            tag: 'Official Circular',
            badgeColor: 'bg-indigo-500',
            title: title,
            subtitle: 'Official School Circular & Vocational Notification',
            date: 'Session 2025-26',
            icon: '📢',
            fileUrl: item.path
          };

          if (customPosters && Array.isArray(customPosters)) {
            customPosters.unshift(newNotice);
          } else {
            const initialPosters = (typeof POSTERS_DATA !== 'undefined') ? [...POSTERS_DATA] : [];
            initialPosters.unshift(newNotice);
            if (typeof saveCustomPosters === 'function') saveCustomPosters(initialPosters);
          }
          customPostersModified = true;
          report.addedNotices.push(newNotice);
          report.logs.push({
            type: 'add',
            icon: '➕',
            msg: `Discovered and added unindexed circular: "${title}" (${item.path})`
          });
        } else {
          // Add unindexed note
          const autoInfo = (typeof Security !== 'undefined' && typeof Security.autoCategorize === 'function')
            ? Security.autoCategorize(item.filename, item.folder)
            : {
                classKey: '9th',
                categoryId: 'part-b',
                categoryName: '💻 Part B: IT Specific Skills',
                cleanTitle: item.filename.replace(/\.pdf$/i, ''),
                folderHeader: item.folder,
                subFolder: item.subfolder
              };

          const newNoteId = 'sshs-auto-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6);
          const newNote = {
            id: newNoteId,
            title: autoInfo.cleanTitle || item.filename.replace(/\.pdf$/i, ''),
            hindiTitle: autoInfo.cleanTitle || item.filename.replace(/\.pdf$/i, ''),
            fileUrl: item.path,
            fileSize: item.size || '1.0 MB',
            pages: 10,
            type: 'PDF',
            uploadedAt: 'Auto-Indexed',
            folderHeader: autoInfo.folderHeader || item.folder,
            subFolder: autoInfo.subFolder || item.subfolder || 'all',
            subjectId: autoInfo.categoryId || 'part-b',
            subjectName: autoInfo.categoryName || '💻 Part B: IT Specific Skills',
            classKey: autoInfo.classKey || '9th',
            isNew: true
          };

          customNotes.unshift(newNote);
          customNotesModified = true;
          report.addedNotes.push(newNote);
          report.logs.push({
            type: 'add',
            icon: '➕',
            msg: `Auto-indexed new note: "${newNote.title}" → Class ${newNote.classKey} (${item.path})`
          });
        }
      }
    }

    // 6. Persist any modifications
    if (customNotesModified && typeof saveCustomNotes === 'function') {
      saveCustomNotes(customNotes);
    }
    if (customPostersModified && typeof saveCustomPosters === 'function') {
      saveCustomPosters(customPosters);
    }
    if (repairedPathsModified && typeof saveRepairedPaths === 'function') {
      saveRepairedPaths(repairedPaths);
    }

    report.totalRepairs = report.repairedNotes.length + report.repairedNotices.length;
    report.totalAdded = report.addedNotes.length + report.addedNotices.length;

    report.logs.push({
      type: 'success',
      icon: '✅',
      msg: `Library Audit Completed: ${report.healthyCount} verified intact, ${report.totalRepairs} path associations repaired, ${report.totalAdded} unindexed files added.`
    });

    // 7. Render UI if modal exists
    if (showModal && typeof this.renderModalResults === 'function') {
      this.renderModalResults(report);
    }

    return report;
  },

  // Render results in the diagnostic modal
  renderModalResults(report) {
    const modal = document.getElementById('librarySyncModal');
    if (!modal) return;

    const elProgress = document.getElementById('syncProgressState');
    const elResults = document.getElementById('syncResultsState');
    const elTotal = document.getElementById('syncTotalFiles');
    const elHealthy = document.getElementById('syncHealthyFiles');
    const elRepaired = document.getElementById('syncRepairedFiles');
    const elAdded = document.getElementById('syncAddedFiles');
    const elBanner = document.getElementById('syncStatusBanner');
    const elLogs = document.getElementById('syncLogsList');
    const elTimestamp = document.getElementById('syncTimestamp');

    if (elProgress) elProgress.style.display = 'none';
    if (elResults) elResults.style.display = 'block';

    if (elTotal) elTotal.textContent = report.totalManifest;
    if (elHealthy) elHealthy.textContent = report.healthyCount;
    if (elRepaired) elRepaired.textContent = report.totalRepairs;
    if (elAdded) elAdded.textContent = report.totalAdded;
    if (elTimestamp) elTimestamp.textContent = `Audited: ${report.timestamp}`;

    if (elBanner) {
      if (report.totalRepairs === 0 && report.totalAdded === 0) {
        elBanner.className = 'sync-status-banner sync-banner-success';
        elBanner.innerHTML = `
          <div class="sync-banner-icon">✅</div>
          <div class="sync-banner-text">
            <strong>100% Verified Healthy &amp; Synced!</strong>
            <div>All ${report.totalManifest} self-hosted physical note and notice files match their respective folder paths with zero broken associations.</div>
          </div>
        `;
      } else {
        elBanner.className = 'sync-status-banner sync-banner-repaired';
        elBanner.innerHTML = `
          <div class="sync-banner-icon">⚡</div>
          <div class="sync-banner-text">
            <strong>Self-Healing Complete!</strong>
            <div>Repaired ${report.totalRepairs} file path associations and auto-indexed ${report.totalAdded} newly discovered physical files into the study portal.</div>
          </div>
        `;
      }
    }

    if (elLogs) {
      elLogs.innerHTML = report.logs.map(log => `
        <div class="sync-log-entry sync-log-${log.type}">
          <span class="sync-log-icon">${log.icon}</span>
          <span class="sync-log-msg">${log.msg}</span>
        </div>
      `).join('');
    }

    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
  }
};

// Global Exports
if (typeof window !== 'undefined') {
  window.PHYSICAL_FILE_MANIFEST = PHYSICAL_FILE_MANIFEST;
  window.LibraryRepairEngine = LibraryRepairEngine;

  // Fully Automatic Repair - NO POPUP OR MODAL
  window.runLibraryRepair = async function(showModal = false) {
    const btn = document.getElementById('btnQuickRepair') || document.querySelector('.btn-library-repair') || document.querySelector('.btn-sync-action');
    let originalText = '';
    if (btn) {
      originalText = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span>⚡</span> <span>Checking &amp; Repairing...</span>';
    }

    try {
      // 1. Run automatic repair across all notes & notices folders silently
      const report = await LibraryRepairEngine.checkAndRepairLibrary({ showModal: false });

      // 2. Automatically refresh data and active view in place
      if (typeof reloadAllData === 'function') {
        await reloadAllData();
        if (typeof currentMode !== 'undefined' && currentMode === 'folder' && typeof selectFolderCategory === 'function') {
          selectFolderCategory(currentFolderCategory, currentSubFolder);
        } else if (typeof currentClass !== 'undefined' && currentClass && typeof selectClass === 'function') {
          selectClass(currentClass);
        }
      }

      if (typeof loadDashboardData === 'function') {
        await loadDashboardData();
        if (typeof renderManageTable === 'function') renderManageTable();
        if (typeof renderManageNotices === 'function') renderManageNotices();
      }

      // 3. Show clean inline toast notification (no pop up!)
      const toastFn = (typeof showToast === 'function') ? showToast : ((typeof showAdminToast === 'function') ? showAdminToast : console.log);
      if (report.totalRepairs > 0 || report.totalAdded > 0) {
        toastFn(`⚡ Auto-repaired ${report.totalRepairs} file(s) and added ${report.totalAdded} new note(s)!`);
      } else {
        toastFn(`✅ All ${report.totalManifest} library files verified intact & healthy!`);
      }
    } catch (err) {
      console.error('Library repair error:', err);
      const toastFn = (typeof showToast === 'function') ? showToast : console.log;
      toastFn('⚠️ Library check finished.');
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = originalText;
      }
    }
  };

  window.closeLibrarySyncModal = function() {
    const modal = document.getElementById('librarySyncModal');
    if (modal) modal.classList.remove('active');
    document.body.style.overflow = 'auto';
  };
}
